SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0690000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 69, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "69", "printedPageNumber": 69, "pdfPageNumber": 452, "sequenceIndex": 59, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0690100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—V", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0690200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—VI", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0690000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (a)—Quotations from the Qur''an", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "In the dictionary ''Ghayy,'' is explained as deception, which points towards the awful doom and ruin in the hereafter. According to many commentators, Ghayy is a pit in Hell full of blood and pus. The persons who had ruined their salaat shall be thrown into this pit.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690200-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690300-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَمَا مَنَعَهُمْ أَنْ تُقْبَلَ مِنْهُمْ نَفَقَاتُهُمْ إِلَّا أَنَّهُمْ كَفَرُوا بِاللَّهِ وَبِرَسُولِهِ وَلَا يَأْتُونَ الصَّلَاةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنْفِقُونَ إِلَّا وَهُمْ كَارِهُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690400-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And naught preventeth that their (the hypocrites) contributions should be accepted from them, save that they have disbelieved in Allah and in His Apostle, and they come not to worship, save as idlers, and pay not (their contribution) save reluctantly.\" (IV: 54)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690500-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Note: The quotations I to V above relate to those who ruin salaat. On the other hand, the following speak of those whom Allah praises for their good salaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690600-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690700-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ ۝ وَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَ ۝ وَالَّذِينَ هُمْ لِلزَّكَاةِ فَاعِلُونَ ۝ وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَىٰ أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَىٰ وَرَاءَ ذَٰلِكَ فَأُولَٰئِكَ هُمُ الْعَادُونَ ۝ وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ ۝ وَالَّذِينَ هُمْ عَلَىٰ صَلَوَاتِهِمْ يُحَافِظُونَ ۝ أُولَٰئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690800-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Successful indeed are the believers who are humble in their salaat. And who shun vain conversation. And who are payers of the Zakaat. And who abstain from sex, save from their wives or the slaves that their right hand possess, for then they are not blameworthy but who craveth beyond that, such are transgressors—And who faithfully observe their pledges and their covenants. And who pay heed to their salaat. These are the heirs who will inherit Firdaus (Paradise). There they will abide.\" (XXIII: 1 to 11)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690900-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Prophet (Sallallaho alaihe wasallam) says, \"Firdaus is the apex and the best portion of Paradise, where", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}]}'::jsonb);